from typing import list

def partition(s: str) -> list[list[str]]:
    def is_palindrome(sub: str) -> bool:
        return sub == sub[::-1]

    def backtrack(start: int, current_partition: list[str]):
        if start == len(s):
            result.append(current_partition[:])
            return

        for end in range(start + 1, len(s) + 1):
            substring = s[start:end]
            if is_palindrome(substring):
                current_partition.append(substring)
                backtrack(end, current_partition)
                current_partition.pop()

    result = []
    backtrack(0, [])
    return result

import re

def evaluate(expression: str) -> float:
    def parse_expression(tokens, pos=0):
        left, pos = parse_term(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(tokens, pos)
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left, pos

    def parse_term(tokens, pos=0):
        left, pos = parse_factor(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_factor(tokens, pos)
            if op == '*':
                left = left * right
            else:
                left = left / right
        return left, pos

    def parse_factor(tokens, pos=0):
        token = tokens[pos]
        if token == '(':
            pos += 1
            result, pos = parse_expression(tokens, pos)
            if pos < len(tokens) and tokens[pos] == ')':
                pos += 1
            return result, pos
        elif token in ('+', '-'):
            # Handle unary plus/minus
            sign = -1 if token == '-' else 1
            pos += 1
            val, pos = parse_factor(tokens, pos)
            return sign * val, pos
        else:
            return float(token), pos + 1

    tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/()]', expression.replace(' ', ''))
    if not tokens:
        raise ValueError("Empty expression")

    result, _ = parse_expression(tokens)
    return float(result)

def long_words(n, text):
    words = text.split()
    return [word for word in words if len(word) > n]
